from pathlib import Path

ROOT = Path('fida-field/app/src/main/java/com/fidalix/fidafield')
cloud_path = ROOT / 'CloudSyncFoundation.java'
main_path = ROOT / 'MainActivity.java'
account_path = ROOT / 'AccountTeamManager.java'
gradle_path = Path('fida-field/app/build.gradle')


def replace_once(text: str, old: str, new: str, label: str) -> str:
    if old not in text:
        raise SystemExit(f'0.9.25 patch failed: {label} pattern not found')
    return text.replace(old, new, 1)

# ---- CloudSyncFoundation: authoritative membership preflight + persistent access state ----
s = cloud_path.read_text()
s = replace_once(
    s,
    '    private static final Object SYNC_LOCK=new Object();\n',
    '    private static final Object SYNC_LOCK=new Object();\n'
    '    public static final String KEY_WORKSPACE_ACCESS_STATE="cloud_workspace_access_state";\n'
    '    public static final String KEY_WORKSPACE_ACCESS_ID="cloud_workspace_access_id";\n'
    '    public static final String KEY_WORKSPACE_ACCESS_CHECKED_AT="cloud_workspace_access_checked_at";\n'
    '    public static final String ACCESS_ACTIVE="Active";\n'
    '    public static final String ACCESS_REVOKED="Revoked";\n'
    '    public static final String ACCESS_UNKNOWN="Unknown";\n',
    'cloud access constants'
)

s = replace_once(
    s,
    '    public String backendStatus(){if(!backendConfigured())return "Not configured";return signedIn()?"Connected":"Configured · sign-in required";}\n',
    '    public String backendStatus(){if(!backendConfigured())return "Not configured";return signedIn()?"Connected":"Configured · sign-in required";}\n'
    '    public String workspaceAccessState(){return prefs.getString(KEY_WORKSPACE_ACCESS_STATE,ACCESS_UNKNOWN);}\n'
    '    public String workspaceAccessCheckedAt(){String v=prefs.getString(KEY_WORKSPACE_ACCESS_CHECKED_AT,"");return v.isEmpty()?"Never":v;}\n'
    '    public boolean workspaceAccessRevoked(String workspaceId){String id=prefs.getString(KEY_WORKSPACE_ACCESS_ID,"");return workspaceId!=null&&!workspaceId.isEmpty()&&workspaceId.equals(id)&&ACCESS_REVOKED.equals(prefs.getString(KEY_WORKSPACE_ACCESS_STATE,ACCESS_UNKNOWN));}\n'
    '    private void markWorkspaceAccess(String workspaceId,String state){prefs.edit().putString(KEY_WORKSPACE_ACCESS_ID,workspaceId==null?"":workspaceId).putString(KEY_WORKSPACE_ACCESS_STATE,state==null?ACCESS_UNKNOWN:state).putString(KEY_WORKSPACE_ACCESS_CHECKED_AT,db.now()).apply();}\n',
    'cloud access state helpers'
)

old_first = '''    public WorkspaceMembership firstWorkspace()throws Exception{\n        Object raw=client.rpc("list_my_workspaces",new JSONObject());\n        if(!(raw instanceof JSONArray)||((JSONArray)raw).length()==0)return null;\n        JSONArray a=(JSONArray)raw;String preferred=prefs.getString(AccountTeamManager.KEY_WORKSPACE_ID,"");JSONObject chosen=null;\n        for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);if(preferred.equals(o.optString("workspace_id"))){chosen=o;break;}}\n        if(chosen==null)chosen=a.getJSONObject(0);\n        return new WorkspaceMembership(chosen.optString("workspace_id"),chosen.optString("workspace_name"),AccountTeamManager.normalizeRole(chosen.optString("role")));\n    }\n'''
new_first = '''    public WorkspaceMembership firstWorkspace()throws Exception{\n        Object raw=client.rpc("list_my_workspaces",new JSONObject());\n        if(!(raw instanceof JSONArray)||((JSONArray)raw).length()==0)return null;\n        JSONArray a=(JSONArray)raw;String preferred=prefs.getString(AccountTeamManager.KEY_WORKSPACE_ID,"");JSONObject chosen=null;\n        for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);if(preferred.equals(o.optString("workspace_id"))){chosen=o;break;}}\n        if(chosen==null)chosen=a.getJSONObject(0);\n        WorkspaceMembership m=new WorkspaceMembership(chosen.optString("workspace_id"),chosen.optString("workspace_name"),AccountTeamManager.normalizeRole(chosen.optString("role")));markWorkspaceAccess(m.id,ACCESS_ACTIVE);return m;\n    }\n\n    public WorkspaceMembership membershipForWorkspace(String workspaceId)throws Exception{\n        if(workspaceId==null||workspaceId.trim().isEmpty())return null;Object raw=client.rpc("list_my_workspaces",new JSONObject());if(!(raw instanceof JSONArray))return null;JSONArray a=(JSONArray)raw;\n        for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);if(workspaceId.equals(o.optString("workspace_id"))){WorkspaceMembership m=new WorkspaceMembership(o.optString("workspace_id"),o.optString("workspace_name"),AccountTeamManager.normalizeRole(o.optString("role")));markWorkspaceAccess(workspaceId,ACCESS_ACTIVE);return m;}}return null;\n    }\n\n    public WorkspaceMembership refreshWorkspaceAccess(String workspaceId)throws Exception{\n        if(!backendConfigured())throw new Exception("Supabase backend is not configured");if(!signedIn())throw new Exception("Please sign in first");WorkspaceMembership m=membershipForWorkspace(workspaceId);\n        if(m==null){markWorkspaceAccess(workspaceId,ACCESS_REVOKED);markSyncResult(false,db.now(),"Workspace access disabled or removed");return null;}\n        prefs.edit().putString(AccountTeamManager.KEY_WORKSPACE_NAME,m.name).putString(AccountTeamManager.KEY_ACCOUNT_ROLE,m.role).putBoolean(AccountTeamManager.KEY_CLOUD_WORKSPACE_BOUND,true).apply();return m;\n    }\n'''
s = replace_once(s, old_first, new_first, 'firstWorkspace membership verification')

old_sync_head = '''            if(!backendConfigured())throw new Exception("Supabase backend is not configured");if(!signedIn())throw new Exception("Please sign in first");if(workspaceId==null||workspaceId.isEmpty())throw new Exception("Cloud workspace is not bound");\n            int pushed=0,pulled=0,deferred=0;if(!canManage)db.discardManagerOnlyPendingChanges();String[] pushOrder=canManage?new String[]{"customer","site","asset","technician","job"}:new String[]{"job"};String[] deleteOrder=canManage?new String[]{"job","asset","site","customer","technician"}:new String[]{"job"};List<AppDatabase.Row> pending=db.pendingBusinessSyncRows();java.util.ArrayList<Long> finalizeCompleted=new java.util.ArrayList<>();java.util.HashSet<String> visibleJobIds=new java.util.HashSet<>();\n'''
new_sync_head = '''            if(!backendConfigured())throw new Exception("Supabase backend is not configured");if(!signedIn())throw new Exception("Please sign in first");if(workspaceId==null||workspaceId.isEmpty())throw new Exception("Cloud workspace is not bound");\n            WorkspaceMembership verified=refreshWorkspaceAccess(workspaceId);if(verified==null)throw new Exception("Workspace access is disabled or has been removed. Ask the workspace Owner/Admin to re-enable your account, then check access again.");canManage=AccountTeamManager.ROLE_OWNER.equals(verified.role)||AccountTeamManager.ROLE_ADMIN.equals(verified.role);\n            int pushed=0,pulled=0,deferred=0;if(!canManage)db.discardManagerOnlyPendingChanges();String[] pushOrder=canManage?new String[]{"customer","site","asset","technician","job"}:new String[]{"job"};String[] deleteOrder=canManage?new String[]{"job","asset","site","customer","technician"}:new String[]{"job"};List<AppDatabase.Row> pending=db.pendingBusinessSyncRows();java.util.ArrayList<Long> finalizeCompleted=new java.util.ArrayList<>();java.util.HashSet<String> visibleJobIds=new java.util.HashSet<>();\n'''
s = replace_once(s, old_sync_head, new_sync_head, 'sync membership preflight')
cloud_path.write_text(s)

# ---- AccountTeamManager: binding an active membership clears any prior revoked state ----
s = account_path.read_text()
old_bind = '''        prefs.edit().putString(KEY_WORKSPACE_ID,clean(cloudWorkspaceId)).putString(KEY_WORKSPACE_NAME,clean(name))\n                .putString(KEY_ACCOUNT_ROLE,normalizedRole).putBoolean(KEY_CLOUD_WORKSPACE_BOUND,true).apply();\n'''
new_bind = '''        prefs.edit().putString(KEY_WORKSPACE_ID,clean(cloudWorkspaceId)).putString(KEY_WORKSPACE_NAME,clean(name))\n                .putString(KEY_ACCOUNT_ROLE,normalizedRole).putBoolean(KEY_CLOUD_WORKSPACE_BOUND,true)\n                .putString(CloudSyncFoundation.KEY_WORKSPACE_ACCESS_ID,clean(cloudWorkspaceId)).putString(CloudSyncFoundation.KEY_WORKSPACE_ACCESS_STATE,CloudSyncFoundation.ACCESS_ACTIVE).apply();\n'''
