old_sync_button = '''        MaterialButton sync=button("Sync now");sync.setEnabled(cloudSync.backendConfigured()&&cloudSync.signedIn()&&accountTeam.hasCloudWorkspace());sync.setOnClickListener(v->runCloud("Synchronizing workspace…",()->cloudSync.syncNow(accountTeam.workspaceId(),accountTeam.canManageTeam()),obj->{CloudSyncFoundation.SyncResult r=(CloudSyncFoundation.SyncResult)obj;refreshEntitlementsAndBranding();toast(r.message);recreate();}));b.addView(sync);\n'''
new_sync_button = '''        if(cloudSync.signedIn()&&accountTeam.hasCloudWorkspace()){MaterialButton accessCheck=outlineButton("Check workspace access");accessCheck.setOnClickListener(v->runCloud("Checking workspace access…",()->cloudSync.refreshWorkspaceAccess(accountTeam.workspaceId()),obj->{CloudSyncFoundation.WorkspaceMembership wm=(CloudSyncFoundation.WorkspaceMembership)obj;if(wm==null){toast("Workspace access is disabled");showWorkspaceAccessBlocked();}else{accountTeam.bindCloudWorkspace(wm.id,wm.name,wm.role);toast("Access active · "+wm.role);showCloudSync();}}));b.addView(accessCheck);}\n        MaterialButton sync=button("Sync now");sync.setEnabled(cloudSync.backendConfigured()&&cloudSync.signedIn()&&accountTeam.hasCloudWorkspace()&&!workspaceAccessRevoked());sync.setOnClickListener(v->runCloud("Synchronizing workspace…",()->cloudSync.syncNow(accountTeam.workspaceId(),accountTeam.canManageTeam()),obj->{CloudSyncFoundation.SyncResult r=(CloudSyncFoundation.SyncResult)obj;refreshEntitlementsAndBranding();toast(r.message);recreate();}));b.addView(sync);\n'''
